let SV=0,M=null,pk={m:'',pf:0,ef:1,ar:3},p,e,proj=[],spark=[],rw=[0,0],round=1,need=2,tm=0,mode='menu',mt=0,mt2=0,msg='',frame=0,shake=0,hs=0,slow=0,hitstop=0,flash=0,cz=1,fz=0,paused=false,lastK='',dmgS=0,pzv='';

