// ===== Audio: procedural punches/whooshes, battle music and announcer voice (no audio files, nothing to download) =====
let ctx,mi,NB,MG,VOX,nxt=0,stp=0,bgm='menu';
const KK=new Set([0,3,6,8,10,14]),ROOT=[82.4,82.4,98,73.4],LEAD=[[[0,659],[3,784],[6,988],[10,784],[14,659]],[[0,659],[3,740],[6,988],[10,740],[14,659]],[[0,784],[3,988],[6,1175],[10,988],[14,784]],[[0,587],[3,740],[6,880],[10,740],[14,587]]];
function ac0(){try{ctx=ctx||new(window.AudioContext||window.webkitAudioContext)();if(ctx.state=='suspended')ctx.resume();if(!MG){MG=ctx.createDynamicsCompressor();MG.connect(ctx.destination);loadSmp()}if(!NB){NB=ctx.createBuffer(1,ctx.sampleRate,ctx.sampleRate);const d=NB.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1}}catch(e){}}
function tone(f,d,ty,v,sl,t0,fc){if(!ctx||S.mute||v<=0)return;try{const t=t0||ctx.currentTime,o=ctx.createOscillator(),g=ctx.createGain();o.type=ty||'square';o.frequency.setValueAtTime(f,t);if(sl)o.frequency.exponentialRampToValueAtTime(Math.max(20,f*sl),t+d);g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.001,t+d);let n=o;if(fc){const b=ctx.createBiquadFilter();b.type='lowpass';b.frequency.value=fc;o.connect(b);n=b}n.connect(g);g.connect(MG||ctx.destination);o.start(t);o.stop(t+d+.02)}catch(e){}}
function nz(d,v,ty,f0,f1,q,t0){if(!ctx||!NB||S.mute||v<=0)return;try{const t=t0||ctx.currentTime,s=ctx.createBufferSource(),b=ctx.createBiquadFilter(),g=ctx.createGain();s.buffer=NB;b.type=ty;b.Q.value=q||1;b.frequency.setValueAtTime(f0,t);b.frequency.exponentialRampToValueAtTime(Math.max(30,f1),t+d);g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.001,t+d);s.connect(b);b.connect(g);g.connect(MG||ctx.destination);s.start(t,Math.random()*.5);s.stop(t+d+.02)}catch(e){}}
const sfx=(f,d,ty,sl)=>tone(f,d,ty,S.sv*.2,sl);
// impacts: noise "slap" + body thump + sub; pitch jitter so repeated hits never sound identical
function punch(k){const v=S.sv,j=.92+Math.random()*.16;
 if(k=='b'){nz(.05,v*.35,'highpass',3000*j,1500,1);tone(760*j,.12,'triangle',v*.22,.45);tone(1180*j,.08,'square',v*.07,.5)}
 else if(k=='l'){if(!smp('sh',v*1.1,j)){nz(.07,v*.7,'bandpass',2200*j,700,1.2);tone(210*j,.1,'sine',v*.55,.45);nz(.03,v*.4,'highpass',4000,2500,1)}}
 else if(k=='h'){if(!smp('kh',v*1.1,j)){nz(.14,v*.85,'lowpass',1400*j,180,.8);tone(130*j,.22,'sine',v*.9,.3);tone(65*j,.3,'sine',v*.8,.5);nz(.05,v*.5,'bandpass',1800,600,1)}}
 else{smp('kh',v*1.2,.8);nz(.5,v*.9,'lowpass',900,60,.7);tone(90,.7,'sine',v,.25);tone(45,.8,'sine',v*.9,.5);nz(.12,v*.6,'bandpass',2500,400,1)}}
function whoosh(k){nz(k=='U'?.35:k=='H'?.2:.12,S.sv*(k=='U'?.5:.28),'bandpass',k=='H'?500:900,k=='H'?2200:2800,1.5)}
function stinger(){const v=S.sv;tone(98,.9,'sawtooth',v*.3,.5,0,900);tone(196,.6,'square',v*.12,.6);nz(1,v*.35,'highpass',4000,1500,1)}
// announcer: Web Speech API (no file). Silently skipped if the browser has no speech voices.
function say(txt,pitch,rate){try{if(S.mute||S.vo===false||!window.speechSynthesis)return;const u=new SpeechSynthesisUtterance(txt);u.lang='en-US';u.pitch=pitch||.5;u.rate=rate||.85;u.volume=Math.min(1,S.sv+.25);const vs=speechSynthesis.getVoices();if(!VOX&&vs.length)VOX=vs.find(v=>/^en/i.test(v.lang)&&/male|david|daniel|alex|fred/i.test(v.name))||vs.find(v=>/^en/i.test(v.lang));if(VOX)u.voice=VOX;speechSynthesis.cancel();speechSynthesis.speak(u)}catch(e){}}
// music: look-ahead scheduler. Calm drone in menus, 150 BPM drums + bass + riff in fights, silent while paused.
function bgmStep(s,t){const B=bgm=='battle',v=paused?0:S.mv;if(v<=0)return;if(B&&SU)return;const bar=(s>>4)&3,st=s&15,r=ROOT[bar];
 if(!B){if(st==0||st==8)tone(r/2,.9,'sawtooth',v*.12,1,t,300);if(st%4==0)tone(r*2,.3,'sine',v*.03,1,t);return}
 if(KK.has(st))tone(150,.2,'sine',v*.55,.3,t);
 if(st==4||st==12){nz(.16,v*.4,'bandpass',1900,900,.9,t);tone(190,.1,'triangle',v*.25,.6,t)}
 if(st%2==0)nz(.04,v*.14,'highpass',7000,6000,1,t);if(st==15)nz(.1,v*.12,'highpass',6000,3000,1,t);
 if(st%2==0)tone(r*(st==6||st==14?2:1),.17,'sawtooth',v*.2,1,t,500+bar*60);
 if(st==0||st==6||st==10)for(let i=0;i<3;i++)tone(r*2*[1,1.5,2][i],.16,'sawtooth',v*.05,1,t,1800);
 const L=LEAD[bar];for(let i=0;i<L.length;i++)if(L[i][0]==st)tone(L[i][1],.2,'square',v*.06,1,t,2500);
 if(st==0&&bar==0)nz(.7,v*.2,'highpass',5000,2500,1,t)}
function sched(){songTick();if(!ctx||S.mute||document.hidden)return;bgm=M&&(mode=='intro'||mode=='fight'||mode=='ko')?'battle':'menu';const now=ctx.currentTime;if(nxt<now)nxt=now+.05;const dur=60/(bgm=='battle'?150:90)/4;while(nxt<now+.2){bgmStep(stp++,nxt);nxt+=dur}}
function music(){if(mi)return;mi=setInterval(sched,40)}
addEventListener('pointerdown',()=>{ac0();music()},{once:true});
// ===== Real sound effects (Mixkit free license): swing clip on attack start, impact clip on hit; plus optional user-loaded fight song =====
const SMP={"sw": "", "sh": "", "kw": "", "kh": ""};
let SB={},SONG=null,SU=null,SU_BLOB=0,CUE=null;const DEFAULT_SONG='shadow-clash-song.mp3',CUE_FILE='321fightSoundeffect.mp3';
function loadSmp(){if(!ctx)return;for(const k in SMP){if(k in SB)continue;SB[k]=null;try{const b=atob(SMP[k]),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);const r=ctx.decodeAudioData(u.buffer,x=>{SB[k]=x},()=>{});if(r&&r.catch)r.catch(()=>{})}catch(e){}}}
function smp(k,v,rate){const b=SB[k];if(!b||!ctx||S.mute)return false;try{const s=ctx.createBufferSource(),g=ctx.createGain();s.buffer=b;s.playbackRate.value=rate||1;g.gain.value=v;s.connect(g);g.connect(MG||ctx.destination);s.start();return true}catch(e){return false}}
function swing(k){const v=S.sv,j=.95+Math.random()*.1;if(k=='L'){if(Math.random()<.65&&smp('sw',v*.9,1.4*j))return}else if(smp('kw',v*.55,(k=='H'?1.25:k=='S'?1.1:.85)*j))return;whoosh(k)}
// fight song chosen by the player (stays on this device: stored in the browser's IndexedDB, never uploaded)
function idb(f){return new Promise((res,rej)=>{try{const r=indexedDB.open('shadowclash',1);r.onupgradeneeded=()=>r.result.createObjectStore('f');r.onsuccess=()=>{const st=r.result.transaction('f',f.w||f.d?'readwrite':'readonly').objectStore('f'),q=f.w?st.put(f.w,'song'):f.d?st.delete('song'):st.get('song');q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)};r.onerror=()=>rej(r.error)}catch(e){rej(e)}})}
function setDefaultSong(){if(SU)return;try{SU=new Audio(DEFAULT_SONG);SU.loop=true;SU.preload='auto';SU_BLOB=0}catch(e){SU=null}}
function setSong(b){if(SU){try{SU.pause();if(SU_BLOB)URL.revokeObjectURL(SU.src)}catch(e){}SU=null}SONG=b||null;if(b){try{SU=new Audio(URL.createObjectURL(b));SU.loop=true;SU.preload='auto';SU_BLOB=1}catch(e){SU=null}}else setDefaultSong()}
idb({}).then(b=>{if(b)setSong(b);else setDefaultSong()}).catch(()=>setDefaultSong());
try{CUE=new Audio(CUE_FILE);CUE.preload='auto'}catch(e){CUE=null}
function playCue(){if(!CUE||S.mute)return;try{CUE.pause();CUE.currentTime=0;const q=CUE.play();if(q&&q.catch)q.catch(()=>{})}catch(e){}}
function pickSong(f){const i=document.createElement('input');i.type='file';i.accept='audio/*';i.onchange=()=>{const fl=i.files&&i.files[0];if(!fl)return;setSong(fl);idb({w:fl}).catch(()=>{});setg(f)};i.click()}
function clearSong(f){setSong(null);idb({d:1}).catch(()=>{});setg(f)}
function songTick(){if(!SU)return;const want=M&&!paused&&!S.mute&&!document.hidden&&(mode=='fight'||mode=='ko'||(mode=='intro'&&round>1));SU.volume=Math.min(1,S.mv*1.6);if(want&&SU.paused){const p=SU.play();if(p&&p.catch)p.catch(()=>{})}else if(!want&&!SU.paused)SU.pause()}

function vib(n){try{!S.nv&&navigator.vibrate&&navigator.vibrate(n)}catch(e){}}

// menus
function ov(h){const m=$('#ov');m.innerHTML=h;m.style.display=h?'flex':'none';document.body.classList.toggle('play',!h);clr()}
const btn=a=>a.map(([t,f])=>`<button class=m onclick="${f}">${t}</button>`).join('');
function main(){M=null;SV=0;mode='menu';paused=false;ov(`<h1>SHADOW CLASH</h1><h2>BLOOD DYNASTY</h2><div class=col>${btn([['ARCADE',"sel('arcade')"],['VERSUS',"sel('versus')"],...(matchMedia('(pointer:coarse)').matches?[]:[['LOCAL 2P',"sel('local')"]]),['TRAINING',"sel('training')"],['SURVIVAL',"sel('survival')"],['SETTINGS',"setg('m')"],['HOW TO PLAY','how()']])}</div><p class=st>WINS ${S.w}  /  LOSSES ${S.l}  /  ARCADE CLEARS ${S.cl}  /  BEST SURVIVAL ${S.bs}</p>${G3?'':'<p class=st>3D UNAVAILABLE - 2D MODE</p>'}`)}
function how(f){ov(`<h2>HOW TO PLAY</h2><p class=bio>Move A / D, jump W, crouch S, sidestep Q / E (corner arrows), dash Shift (DSH). Light J, heavy K, special L (50% energy), block I, ultimate Space (full energy). Esc pauses.<br><br>On touch (PlayStation-style buttons: Square light, Cross heavy, Triangle special, Circle ultimate, R1 guard, R2 dash; button art 'UI Elements' by Arks @scissormarks, arks.itch.io/ps4-buttons): use the circular joystick on the left to move, jump, and crouch; use the round buttons on the right to attack and defend. Hits fill your energy bar. Light attacks miss crouching enemies, so crouch to dodge them. Crouch + heavy is a launcher: follow up in the air to juggle. Heavy hits and ultimates knock down; the get-up is invulnerable. Hitboxes are real: high punches whiff crouching foes, low attacks (crouch + light/heavy) beat a standing guard, so crouch + block to stop them. A landed hit cancels into a stronger move: LT to LT/HV/SP/ULT, HV to SP/ULT, SP to ULT (max 3 links). Hitting a foe mid-attack is a COUNTER (+25%). Blocking causes blockstun; ultimates break guard; teleports can cross-up. Settings: HITBOXES shows boxes, TRAINING DUMMY sets its guard. LOCAL 2P (keyboard): arrows move, Comma light, Period heavy, Slash special, Right Shift block, Enter ultimate. Blocking cuts damage but ultimates break guards. Chain hits for combos; long combos deal less damage. Win 2 of 3 rounds. A final-round KO with a special or ultimate triggers a finisher.</p><button class=g onclick="${f=='p'?'pauseScr()':'main()'}">BACK</button>`)}
function setg(f){ov(`<h2>SETTINGS</h2><label>MUSIC <input type=range min=0 max=1 step=.05 value=${S.mv} oninput="S.mv=+this.value;put()"></label><label>EFFECTS <input type=range min=0 max=1 step=.05 value=${S.sv} oninput="S.sv=+this.value;put()"></label><label><input type=checkbox ${S.mute?'checked':''} onchange="S.mute=this.checked?1:0;put()"> MUTE</label><button class=m onclick="S.df=(S.df+1)%4;put();setg('${f}')">AI LEVEL: ${DF[S.df]}</button><button class=m onclick="S.hb=!S.hb;put();setg('${f}')">HITBOXES: ${S.hb?'ON':'OFF'}</button>${G3?`<button class=m onclick="S.gq=((S.gq==null?1:S.gq)+1)%3;AQ=0;put();applyGQ();setg('${f}')">GRAPHICS: ${['LOW','MEDIUM','HIGH'][S.gq==null?1:S.gq]}</button>`:''}<button class=m onclick="S.dm=((S.dm||0)+1)%3;put();setg('${f}')">TRAINING DUMMY: ${['IDLE','BLOCK','CROUCH BLOCK'][S.dm||0]}</button><button class=m onclick="S.nv=!S.nv;put();setg('${f}')">VIBRATION: ${S.nv?'OFF':'ON'}</button><button class=m onclick="S.vo=S.vo===false;put();setg('${f}')">ANNOUNCER: ${S.vo===false?'OFF':'ON'}</button><button class=m onclick="pickSong('${f}')">FIGHT SONG: ${SONG?'YOURS (tap to change)':'DEFAULT (tap to load yours)'}</button>${SONG?`<button class=g onclick="clearSong('${f}')">REMOVE MY SONG</button>`:''}<button class=g onclick="S.w=S.l=S.cl=S.bs=0;put();setg('${f}')">RESET STATS</button><button class=g onclick="${f=='p'?'pauseScr()':'main()'}">BACK</button>`)}
function sel(m){pk.m=m;selScr()}
function fb(k){return FIG.map((f,i)=>`<button class="f${pk[k]==i?' on':''}" style="--c:${f.a}" onclick="pk.${k}=${i};selScr()">${f.n}</button>`).join('')}
function selScr(){SV=1;mode='menu';const f=FIG[pk.pf],v=pk.m=='versus'||pk.m=='local',fx=pk.m=='arcade'||pk.m=='survival';
 ov(`<h2>${pk.m.toUpperCase()}</h2><p class=lb>YOUR FIGHTER</p><div class=row>${fb('pf')}</div><div class=sb><span>SPEED</span><i style="--v:${f.sp/5.2*100}%"></i></div><div class=sb><span>POWER</span><i style="--v:${f.dm/10*100}%"></i></div><p class=bio>${f.bio}<br>SPECIAL: ${f.sn}  /  ULTIMATE: ${f.un}</p>${v?`<p class=lb>OPPONENT</p><div class=row>${fb('ef')}</div>`:''}${fx?'':`<p class=lb>ARENA</p><div class=row>${AR.map((n,i)=>`<button class="f${pk.ar==i?' on':''}" onclick="pk.ar=${i};selScr()">${n}</button>`).join('')}</div>`}${pk.m!='local'&&(v||fx)?`<button class=g onclick="S.df=(S.df+1)%4;put();selScr()">AI LEVEL: ${DF[S.df]}</button>`:''}<button class=m onclick="go()">FIGHT</button><button class=g onclick="main()">BACK</button>`)}
function go(){SV=0;ac0();music();
 M={mode:pk.m,pf:pk.pf,ar:pk.ar,df:S.df,n:0,carry:100,ef:pk.ef};
 if(M.mode=='arcade'){const o=FIG.map((_,i)=>i).filter(i=>i!=M.pf).sort(()=>Math.random()-.5).slice(0,4);M.q=[...o,'b'];M.ef=M.q[0];M.ar=3}
 if(M.mode=='survival'){M.ef=rf();M.ar=Math.random()*4|0}
 if(M.mode=='training')M.ef=pk.ef;
 begin()}
const rf=()=>Math.random()*FIG.length|0;
function begin(){ov('');paused=false;rw=[0,0];round=1;M.mc=0;if(SU)SU.currentTime=0;need=M.mode=='survival'?1:2;newRound()}
function res(t,s,b){const w=/VICT|WINS|CLEARED|SURVIVED/.test(t);ov(`<h1 style="font-size:clamp(30px,8vw,54px);color:${w?'#ffb703':'#c1121f'}">${t}</h1><p class=bio>${s}</p><p class=st>ROUNDS ${rw[0]} - ${rw[1]}  /  BEST COMBO ${M.mc||0}</p><div class=col>${btn(b)}</div>`);if(w)sfx(660,.4,'triangle',1.5);else sfx(110,.6,'sawtooth',.5)}
function done(win){const m=M;if(m.mode=='local'){res(win?'PLAYER 1 WINS':'PLAYER 2 WINS','',[['REMATCH','begin()'],['CHARACTER SELECT','selScr()'],['MENU','main()']]);return}if(win)S.w++;else S.l++;put();
 if(m.mode=='versus'){res(win?'VICTORY':'DEFEAT','',[['REMATCH','begin()'],['CHARACTER SELECT','selScr()'],['MENU','main()']]);return}
 if(m.mode=='arcade'){
  if(!win){res('DEFEAT','The dynasty stands.',[['RETRY','begin()'],['MENU','main()']]);return}
  m.n++;
  if(m.n>=m.q.length){S.cl++;put();res('ARCADE CLEARED','Malakor falls. Clears: '+S.cl,[['PLAY AGAIN','go()'],['MENU','main()']]);return}
  m.ef=m.q[m.n];m.ar=(3+m.n)%4;res('VICTORY','Next opponent: '+fd(m.ef).n,[['CONTINUE','begin()'],['MENU','main()']]);return}
 if(win){m.n++;m.carry=Math.min(100,p.hp+35);m.ef=rf();m.ar=Math.random()*4|0;m.df=Math.min(3,S.df+(m.n/3|0));res('SURVIVED','Fights won: '+m.n+'. Health restored to '+Math.round(m.carry)+'.',[['NEXT FIGHT','begin()'],['MENU','main()']])}
 else{S.bs=Math.max(S.bs,m.n);put();res('ELIMINATED','Fights won: '+m.n+'. Best: '+S.bs,[['TRY AGAIN','go()'],['MENU','main()']])}}
function pauseScr(){ov(`<h2>PAUSED</h2><p class=st>${M.mode.toUpperCase()}  /  ROUND ${round}  /  ${rw[0]} - ${rw[1]}</p><div class=col>${btn([['RESUME','resume()'],['RESTART','begin()'],['SETTINGS',"setg('p')"],['HOW TO PLAY',"how('p')"],['MAIN MENU','main()']])}</div>`)}
function pause(){if(mode=='menu'||mode=='end'||mode=='over'||paused)return;paused=true;clr();pauseScr()}
function resume(){paused=false;ov('')}

