 if((ps=='hurt'||ps=='down')&&a.st=='idle'){ai.s='rec';ai.w=[22,14,8,5][df];ai.plan=[]}
 else if(ps=='atk'&&a.st=='idle'){ai.s='rec';ai.w=[16,10,6,3][df];ai.plan=[]}
 // busy: only chain cancels, same rules as the player
 if(a.st!='idle'){if(a.st=='atk'&&a.cn&&ai.plan&&ai.plan.length&&R()<Q.ag+.2)i[ai.plan.shift()]=1;return i}
 // defense
 const fr=ai.pb&&!a.bst;ai.pb=a.bst>0;
 if(ob.st=='atk'&&!ai.pa){ai.df=R()<Q.bl;ai.dl=ob.lo}
 ai.pa=ob.st=='atk';
 const th=proj.find(z=>z.o===o&&z.vx*(a.x-z.x)>0&&Math.abs(z.x-a.x)<230);
 if(th&&!ai.pj)ai.pd=R()<Q.bl;ai.pj=!!th;
 if(th&&ai.pd){if(df==0)i.b=1;else if(df>=2&&R()<.5)i.zs=R()<.5?1:-1;else i.c=1;return i}
 if(ai.pa&&ai.df&&ad<(ob.k=='U'?170:ob.k=='H'?116:100)){if(ob.k=='U'&&df>=2){i.j=1;i[bw]=1}else{i.b=1;i.c=ai.dl?1:0}return i}
 // punish: guard released while the attacker may still be recovering
 if(fr&&ad<100&&R()<Q.pu){i[ad<72?'L':'H']=1;return i}
 // recover: reset spacing
 if(ai.w>0)ai.w--;
 if(ai.s=='rec'){if(ai.w>0){if(ad<95&&!cor)i[bw]=1;return i}ai.s='neu'}
 // neutral: spacing, approach, attack selection
 const tk=!(ai.w>0);if(tk)ai.w=Q.dc+(R()*Q.dc|0);
